import{_ as l,a0 as p,w as r,s as o,ao as d,I as i,x as s,a1 as n,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"機器學習：使用 Python 進行分類 | LCTT x X-CMD","titleTemplate":false,"description":"機器學習：使用 Python 進行分類 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"機器學習：使用 Python 進行分類 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"機器學習：使用 Python 進行分類 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220525 Machine Learning- Classification Using Python","title":"機器學習：使用 Python 進行分類","tag":"202206","desc":""},"relativePath":"202206/20220525 Machine Learning- Classification Using Python.md","filePath":"[post].md"}'),f={name:"202206/20220525 Machine Learning- Classification Using Python.md"};function h(c,t,g,y,u,b){const a=p("Link");return r(),o("div",null,[t[15]||(t[15]=d(`<h1 id="機器學習-使用-python-進行分類" tabindex="-1">機器學習：使用 Python 進行分類 <a class="header-anchor" href="#機器學習-使用-python-進行分類" aria-label="Permalink to “機器學習：使用 Python 進行分類”">​</a></h1><blockquote><p>機器學習（ML）就是，分析一組數據以預測結果。Python 被認為是 ML 的最佳編程語言選擇之一。在本文中，我們將討論使用 Python 進行分類的機器學習。</p></blockquote><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/machine-learning-classification.jpg" alt="machine-learning-classification"></p><p>假設你想教孩子區分蘋果和橙子。有多種方法可以做到這一點。你可以讓孩子觸摸這兩種水果，讓他們熟悉形狀和柔軟度。你還可以向她展示蘋果和橙子的多個例子，以便他們可以直觀地發現差異。這個過程的技術等價物被稱為機器學習。</p><p>機器學習教計算機解決特定問題，並通過經驗變得更好。這裏討論的示例是一個分類問題，其中機器被賦予各種標記示例，並期望使用它從標記樣本中獲得的知識來對未標記樣本進行標記。機器學習問題也可以採用迴歸的形式，其中期望根據已知樣本及其解決方案來預測給定問題的<ruby>實值<rt>real-valued</rt></ruby>解決方案。<ruby>分類<rt>Classification</rt></ruby>和<ruby>迴歸<rt>Regression</rt></ruby>被廣泛稱為<ruby>監督學習<rt>supervised learning</rt></ruby>。機器學習也可以是<ruby>無監督<rt>unsupervised</rt></ruby>的，機器識別未標記數據中的模式，並形成具有相似模式的樣本集羣。機器學習的另一種形式是<ruby>強化學習<rt>reinforcement learning</rt></ruby>，機器通過犯錯從環境中學習。</p><h3 id="分類" tabindex="-1">分類 <a class="header-anchor" href="#分類" aria-label="Permalink to “分類”">​</a></h3><p>分類是根據從已知點獲得的信息來預測一組給定點的標籤的過程。與一個數據集相關的類別或標籤可以是二元的，也可以是多元的。舉例來説，如果我們必須給與一個句子相關的情緒打上標籤，我們可以把它標記為正面、負面或中性。另一方面，我們必須預測一個水果是蘋果還是橘子的問題將有二元標籤。表 1 給出了一個分類問題的樣本數據集。</p><p>在該表中，最後一列的值，即貸款批准，預計將基於其他變量進行預測。在接下來的部分中，我們將學習如何使用 Python 訓練和評估分類器。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">年齡</th><th style="text-align:left;">信用等級</th><th style="text-align:left;">工作</th><th style="text-align:left;">擁有房產</th><th style="text-align:left;">貸款批准</th></tr></thead><tbody><tr><td style="text-align:left;">35</td><td style="text-align:left;">好</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td></tr><tr><td style="text-align:left;">32</td><td style="text-align:left;">差</td><td style="text-align:left;">是</td><td style="text-align:left;">不</td><td style="text-align:left;">不</td></tr><tr><td style="text-align:left;">22</td><td style="text-align:left;">一般</td><td style="text-align:left;">不</td><td style="text-align:left;">不</td><td style="text-align:left;">不</td></tr><tr><td style="text-align:left;">42</td><td style="text-align:left;">好</td><td style="text-align:left;">是</td><td style="text-align:left;">不</td><td style="text-align:left;">是</td></tr></tbody></table></div><p><em>表 1</em></p><h3 id="訓練和評估分類器" tabindex="-1">訓練和評估分類器 <a class="header-anchor" href="#訓練和評估分類器" aria-label="Permalink to “訓練和評估分類器”">​</a></h3><p>為了訓練<ruby>分類器<rt>classifier</rt></ruby>，我們需要一個包含標記示例的數據集。儘管本節不涉及清理數據的過程，但建議你在將數據集輸入分類器之前閲讀各種數據預處理和清理技術。為了在 Python 中處理數據集，我們將導入 <code>pandas</code> 包和<ruby>數據幀<rt>DataFrame</rt></ruby>結構。然後，你可以從多種分類算法中進行選擇，例如<ruby>決策樹<rt>decision tree</rt></ruby>、<ruby>支持向量分類器<rt>support vector classifier</rt></ruby>、<ruby>隨機森林<rt>random forest</rt></ruby>、XG boost、ADA boost 等。我們將看看隨機森林分類器，它是使用多個決策樹形成的集成分類器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from sklearn.ensemble import RandomForestClassifier</span></span>
<span class="line"><span>from sklearn import metrics</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>classifier = RandomForestClassifier()</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>#creating a train-test split with a proportion of 70:30</span></span>
<span class="line"><span>X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.33)</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>classifier.fit(X_train, y_train) # 在訓練集上訓練分類器</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>y_pred = classifier.predict(X_test) # 用未知數據評估分類器</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>print(&quot;Accuracy: &quot;, metrics.accuracy_score(y_test, y_pred)) # 用測試計劃中的實際值比較準確率</span></span></code></pre></div><p>雖然這個程序使用準確性作為性能指標，但應該使用多種指標的組合，因為當測試集不平衡時，準確性往往會產生非代表性的結果。例如，如果模型對每條記錄都給出了相同的預測，而用於測試模型的數據集是不平衡的，即數據集中的大多數記錄與模型預測的類別相同，我們就會得到很高的準確率。</p><h3 id="調整分類器" tabindex="-1">調整分類器 <a class="header-anchor" href="#調整分類器" aria-label="Permalink to “調整分類器”">​</a></h3><p>調優是指修改模型的<ruby>超參數<rt>hyperparameter</rt></ruby>值以提高其性能的過程。超參數是可以改變其值以改進算法的學習過程的參數。</p><p>以下代碼描述了隨機搜索超參數調整。在此，我們定義了一個搜索空間，算法將從該搜索空間中選擇不同的值，並選擇產生最佳結果的那個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from sklearn.model_selection import RandomizedSearchCV</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#define the search space</span></span>
<span class="line"><span>min_samples_split = [2, 5, 10]</span></span>
<span class="line"><span>min_samples_leaf = [1, 2, 4]</span></span>
<span class="line"><span>grid = {‘min_samples_split’ : min_samples_split, ‘min_samples_leaf’ : min_samples_leaf}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>classifier = RandomizedSearchCV(classifier, grid, n_iter = 100)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># n_iter 代表從搜索空間提取的樣本數</span></span>
<span class="line"><span># result.best_score 和 result.best_params_ 可以用來獲得模型的最佳性能，以及參數的最佳值</span></span>
<span class="line"><span></span></span>
<span class="line"><span>classifier.fit(X_train, y_train)</span></span></code></pre></div><h3 id="投票分類器" tabindex="-1">投票分類器 <a class="header-anchor" href="#投票分類器" aria-label="Permalink to “投票分類器”">​</a></h3><p>你也可以使用多個分類器和它們的預測來創建一個模型，根據各個預測給出一個預測。這個過程（只考慮為每個預測投票的分類器的數量）被稱為硬投票。軟投票是一個過程，其中每個分類器產生一個給定記錄屬於特定類別的概率，而投票分類器產生的預測是獲得最大概率的類別。</p><p>下面給出了一個創建軟投票分類器的代碼片段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>soft_voting_clf = VotingClassifier(</span></span>
<span class="line"><span>estimators=[(‘rf’, rf_clf), (‘ada’, ada_clf), (‘xgb’, xgb_clf), (‘et’, et_clf), (‘gb’, gb_clf)],</span></span>
<span class="line"><span>voting=’soft’)</span></span>
<span class="line"><span>soft_voting_clf.fit(X_train, y_train)</span></span></code></pre></div><p>這篇文章總結了分類器的使用，調整分類器和結合多個分類器的結果的過程。請將此作為一個參考點，詳細探討每個領域。</p><hr>`,24)),i("p",null,[t[1]||(t[1]=s("via: ",-1)),n(a,{href:"https://www.opensourceforu.com/2022/05/machine-learning-classification-using-python/"},{default:e(()=>[...t[0]||(t[0]=[s("https://www.opensourceforu.com/2022/05/machine-learning-classification-using-python/",-1)])]),_:1})]),i("p",null,[t[6]||(t[6]=s("作者：",-1)),n(a,{href:"https://www.opensourceforu.com/author/gayatri-venugopal/"},{default:e(()=>[...t[2]||(t[2]=[s("Gayatri Venugopal",-1)])]),_:1}),t[7]||(t[7]=s(" 選題：",-1)),n(a,{href:"https://github.com/lkxed"},{default:e(()=>[...t[3]||(t[3]=[s("lkxed",-1)])]),_:1}),t[8]||(t[8]=s(" 譯者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:e(()=>[...t[4]||(t[4]=[s("geekpi",-1)])]),_:1}),t[9]||(t[9]=s(" 校對：",-1)),n(a,{href:"https://github.com/turbokernel"},{default:e(()=>[...t[5]||(t[5]=[s("turbokernel",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=s("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[10]||(t[10]=[s("LCTT",-1)])]),_:1}),t[13]||(t[13]=s(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:e(()=>[...t[11]||(t[11]=[s("Linux中國",-1)])]),_:1}),t[14]||(t[14]=s(" 榮譽推出",-1))])])}const k=l(f,[["render",h]]);export{x as __pageData,k as default};
